<script setup lang="ts">
import StableLabel from '../../shared/StableLabel.vue';
import {computed,ref,watch,onUnmounted,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import MeetingLibraryView from './MeetingLibraryView.vue';import {useMeetingLibrary,type LibraryRow} from './useMeetingLibrary';
const app=useApplication(),route=useRoute(),router=useRouter(),actor=()=>app.session.current.value?.actor.enterpriseId??null,mode=ref<'read'|'manage'>('read'),library=useMeetingLibrary({library:app.meetingLibrary},actor,()=>mode.value),governanceError=ref('');
const libraryId=computed(()=>typeof route.params.id==='string'?route.params.id:null),visible=computed(()=>library.rows.value.filter(row=>!libraryId.value||row.context.libraryId===libraryId.value)),selected=computed(()=>visible.value[0]?.context??null),sourceInLibrary=computed(()=>visible.value.find(row=>row.meeting.id===route.query.meeting)??null);
const groups=computed(()=>{const entries=new Map<string,LibraryRow[]>();for(const row of library.rows.value){const key=JSON.stringify([row.context.providerId,row.context.storeInstanceId,row.context.libraryId]);const group=entries.get(key)??[];group.push(row);entries.set(key,group);}return [...entries.values()].map(rows=>({key:JSON.stringify([rows[0]!.context.providerId,rows[0]!.context.storeInstanceId,rows[0]!.context.libraryId]),context:rows[0]!.context,rows}));});
const stateLabels:Record<string,string>={ACTIVE:'已发布',UNKNOWN:'状态待核实',WITHDRAW_PENDING:'撤回处理中',OBSOLETE_PENDING:'废止处理中',WITHDRAWN:'已撤回',OBSOLETE:'已废止'};
function open(row:LibraryRow){if(row.context.canRead)window.open(row.context.documentUrl,'_blank','noopener');}function home(){void router.push('/meetings');}function back(){if(sourceInLibrary.value)void router.push(`/meeting/${sourceInLibrary.value.meeting.id}/read`);}
async function govern(row:LibraryRow){governanceError.value='';try{if(!row.context.canManage)return;app.setMeetingScope(row.meeting.id);await nextTick();app.governanceCommands.open(row.context.publicationId,row.context.meetingRevisionToken,row.context.state==='ACTIVE');}catch(cause){governanceError.value=cause instanceof Error?cause.message:'治理操作暂不可用，请重新查询。';}}
const stopIdentity=watch(actor,()=>{governanceError.value='';library.invalidate();void library.refresh();},{immediate:true,flush:'sync'}),stopMode=watch(mode,()=>void library.refresh());
watch(()=>app.governanceCommands.job.value?.state,state=>{if(state==='SUCCEEDED'||state==='CONFLICT')void library.refresh();});
onUnmounted(()=>{stopIdentity();stopMode();library.dispose();});
</script>
<template><div class="layout"><div class="main"><main class="content" :aria-busy="library.loading.value"><div class="page-actions mb16"><button class="btn" :disabled="library.loading.value" @click="library.refresh">重新读取</button></div>
 <div v-if="library.error.value||governanceError" class="banner error" role="alert">{{library.error.value||governanceError}}</div>
 <div v-if="library.hasManagedLibraries.value||mode==='manage'" class="tabs"><button class="tab" :class="{active:mode==='read'}" @click="mode='read'">正式知识文档</button><button class="tab" :class="{active:mode==='manage'}" @click="mode='manage'">发布与撤回记录</button></div>
 <template v-if="mode==='manage'"><div class="page-head"><div><div class="page-title">发布与撤回记录</div><div class="page-desc">仅显示当前账号管理范围内的知识文档；历史记录保留，撤回或废止后不提供恢复发布。</div></div></div><div class="card"><div class="table-wrap"><table class="tbl"><thead><tr><th>知识文档 / 来源会议</th><th>知识库及路径</th><th>发布版本</th><th>发布人 / 时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.context.documentId"><td><b>{{row.context.title}}</b><div class="small muted">{{row.meeting.name}}</div><div class="small mono">{{row.context.documentId}}</div></td><td>{{row.context.libraryName}} / {{row.context.folderPath.join(' / ')}}</td><td>V{{row.context.publishedVersion}}</td><td>{{row.context.publishedBy}}<div class="small muted">{{row.context.publishedAt}}</div></td><td><span class="tag">{{stateLabels[row.context.state]}}</span></td><td><div class="flex wrap"><button v-if="row.context.canRead" class="btn sm" @click="open(row)">查看正式文档</button><button v-if="row.context.canManage" class="btn sm" @click="govern(row)">{{row.context.state==='ACTIVE'?'撤回 / 标记废止':'治理记录'}}</button></div></td></tr></tbody></table><div v-if="!visible.length" class="empty">{{library.loading.value?'正在读取记录…':'当前管理范围内暂无发布记录'}}</div></div></div></template>
 <template v-else-if="!libraryId"><div class="page-head"><div><div class="page-title">会议知识库</div><div class="page-desc">查看当前账号按知识库权限可读取的已发布会议成果</div></div></div><div class="card card-p"><div v-for="group in groups" :key="group.key" class="file-item"><div style="flex:1;min-width:0"><RouterLink class="m19-name" :to="'/meeting-library/'+encodeURIComponent(group.context.libraryId)">{{group.context.libraryName}}</RouterLink><div class="small muted mt8">已读取 {{group.rows.length}} 份当前可访问的会议纪要</div></div></div><div v-if="!groups.length" class="empty">{{library.loading.value?'正在读取正式文档…':'暂无有权查看的会议纪要'}}</div></div></template>
 <MeetingLibraryView v-else :library="selected" :rows="visible" :source="sourceInLibrary" :loading="library.loading.value" :unavailable="!library.hasMore.value" @home="home" @back="back" @open="open"/>
 <div v-if="library.hasMore.value||library.error.value" class="pager"><button class="btn" :disabled="library.loading.value" @click="library.more"><StableLabel :labels="['重试当前页','继续读取记录']">{{library.error.value?'重试当前页':'继续读取记录'}}</StableLabel></button></div><p v-if="library.hasMore.value" class="small muted mt8">当前展示已读取的记录，继续读取可查看后续条目。</p>
 </main></div></div></template>
<style scoped>.tbl td{vertical-align:top;overflow-wrap:anywhere}.tbl td:first-child{max-width:320px}.tbl td:nth-child(2){max-width:300px}</style>
